function getURLSearchParams() {
	return ((searchParams) => {
		const e = new URLSearchParams(searchParams);
		const i: { [k: string]: string } = {};
		for (const t of e.entries()) {
			i[t[0]] = t[1];
		}
		return i;
	})(location.search);
}
