async function Mt(href: string, init: RequestInit & { timeout?: number } = {}) {
	const { timeout = 8000 } = init;
	const s = new AbortController();
	const n = setTimeout(() => s.abort(), timeout);
	init.signal = s.signal;
	const o = await fetch(href, init);
	clearTimeout(n);
	return o;
}
