		if (forwardVec.clone().cross(flatDir).y > 0) {
			yawAngle = -yawAngle;
		}
		let pitchAngle = forwardDir.angleTo(flatDir);
		if (forwardDir.clone().cross(flatDir).dot(rightDir) > 0) {
			pitchAngle = -pitchAngle;
		}
