class GameEndTimer {
	timeSeconds;
	name;
	running = false;
	startTime = 0;
	onSuddenChangeCbs = new Set();
	constructor(t = 0, e = "") {
		this.timeSeconds = t;
		this.name = e;
	}
	setTotalTime(t) {
		this.timeSeconds = t;
	}
	start() {
		this.running = true;
		this.startTime = Date.now();
	}
	clear() {
		const t = this.timeRemaining > 1;
		this.cleared = true;
		if (t) {
			this.onSuddenChangeCbs.forEach((t) => t());
		}
	}
	onSuddenChange(t) {
		this.onSuddenChangeCbs.add(t);
	}
	get timeRemaining() {
		if (this.cleared) {
			return 0;
		}
		if (this.running) {
			const t = (Date.now() - this.startTime) / 1000;
			return Math.max(0, this.timeSeconds - t);
		}
		return this.timeSeconds;
	}
	toString() {
		let timeRemaining = this.timeRemaining;
		timeRemaining = Math.round(10 * timeRemaining) / 10;
		return `<${this.name} ${timeRemaining}>`;
	}
}
