class MapCollider extends ColliderBase {
	radius;
	pos = new Vector3();
	constructor(worldMatrix: Matrix4, opts) {
		super(worldMatrix, opts);
		this.radius = this.worldMatrix.getMaxScaleOnAxis();
		this.pos.setFromMatrixPosition(this.worldMatrix);
		const e = this.pos.clone().subScalar(this.radius);
		const i = this.pos.clone().addScalar(this.radius);
		this.aabb = new Box3(e, i);
	}
	override getSphereManifold(t: Vector3, e: number): SphereManifold {
		return ze(t, e, this.pos, this.radius);
	}
	override rayCast(from: Vector3, dir: Vector3): RayCastHit | null {
		const i = this.pos.clone().sub(from);
		const s = i.length();
		if (s < this.radius) {
			return {
				dist: 0,
				pos: from.clone(),
				collider: this,
			};
		}
		const n = i.clone().projectOnVector(dir);
		if (n.dot(dir) < 0) {
			return null;
		}
		const o = n.length();
		const a = Math.sqrt(s ** 2 - o ** 2);
		if (a > this.radius) {
			return null;
		}
		const dist = o - Math.sqrt(this.radius ** 2 - a ** 2);
		const l = dir.clone();
		l.setLength(dist);
		return {
			pos: from.clone().add(l),
			dist,
			collider: this,
		};
	}
}
class OctreeNode {
	items: ColliderBase[] = [];
	allChildren: OctreeNode[] = [];
	children = new Set<OctreeNode>();
	constructor(
		public aabb: Box3,
		public depth = 0,
	) {}
	addItems(items) {
		for (const item of items) {
			this.items.push(item);
		}
	}
	subdivideRecursive({ boundsContainsCb, maxDepth, itemCountDivideLimit }) {
		if (!(this.depth >= maxDepth || this.items.length <= itemCountDivideLimit)) {
			this.subdivide();
			for (const s of this.children) {
				for (const e of this.items) {
					if (boundsContainsCb(e, s.aabb)) {
						s.addItems([e]);
					}
				}
				if (s.items.length <= 0) {
					this.children.delete(s);
				} else {
					s.subdivideRecursive({
						boundsContainsCb,
						maxDepth,
						itemCountDivideLimit,
					});
				}
			}
			this.items = [];
		}
	}
	subdivide() {
		const min = this.aabb.min;
		const max = this.aabb.max;
		const i = this.aabb.getCenter(new Vector3());
		for (let index = 0; index < 8; index++) {
			const n = new Box3();
			if (index % 2 < 1) {
				n.min.x = min.x;
				n.max.x = i.x;
			} else {
				n.min.x = i.x;
				n.max.x = max.x;
			}
			if (index % 4 < 2) {
				n.min.y = min.y;
				n.max.y = i.y;
			} else {
				n.min.y = i.y;
				n.max.y = max.y;
			}
			if (index < 4) {
				n.min.z = min.z;
				n.max.z = i.z;
			} else {
				n.min.z = i.z;
				n.max.z = max.z;
			}
			const node = new OctreeNode(n, this.depth + 1);
			this.children.add(node);
			this.allChildren[index] = node;
		}
	}
	*traverseDown(t = () => true) {
		if (t(this)) {
			yield this;
			for (const e of this.children) {
				for (const i of e.traverseDown(t)) {
					yield i;
				}
			}
		}
	}
	*findEndNodes(t = () => true) {
		for (const e of this.traverseDown(t)) {
			if (e.items.length != 0) {
				yield e;
			}
		}
	}
}
