		windSfxBoostVolume: 0,
		windSfxBoostHeight: 0,
		birdsSfxVolume: 0.003,
		jungleSfxVolume: 0,
		rainSfxVolume: 0,
		insectsSfxVolume: 0,
		skyHighColor: [0, 0.415, 0.96],
		skyMidColor: [0.807, 0.89, 0.933],
		skyLowColor: [0.807, 0.89, 0.933],
		skyPower: 0.6,
		fogAmount: 0.002,
		fogHeightAmount: 0,
		fogHeightOffset: 0,
		fogHeightDistFalloff: 0,
		fogHeightAmountMin: 0,
