		if (!mapHashes) {
			return null;
		}
		return {
			op: "preferredMapHashes",
			mapHashes,
			configTimestamp: this.mapsConfigLoader.loadedConfigData.lastUpdatedTimestamp,
			allowPreferredOnly: Boolean(this.forcingSoloMap),
		};
