				this.ctx.listener.forwardY.value = i.y;
				this.ctx.listener.forwardZ.value = i.z;
				this.ctx.listener.upX.value = s.x;
				this.ctx.listener.upY.value = s.y;
				this.ctx.listener.upZ.value = s.z;
